lookup_query_templates.validate(film_director):
SELECT ?work (GROUP_CONCAT(DISTINCT STR(?c);separator="|") AS ?creators)
  (GROUP_CONCAT(DISTINCT CONCAT(STR(?t), "@", STR(?prec));separator="|") AS ?dates)
  (GROUP_CONCAT(DISTINCT STR(?k);separator="|") AS ?kinds) WHERE {
  VALUES ?work { wd:Q1 }
  OPTIONAL { ?work wdt:P57 ?c }
  OPTIONAL { ?work p:P577 ?st. ?st wikibase:rank ?rk; psv:P577 ?tv.
    ?tv wikibase:timeValue ?t; wikibase:timePrecision ?prec.
    FILTER(?rk != wikibase:DeprecatedRank) }
  OPTIONAL { ?work wdt:P31|wdt:P7937|wdt:P136 ?k }
} GROUP BY ?work

lookup_query_templates.creator:
SELECT ?creator ?label ?human ?sl (GROUP_CONCAT(DISTINCT STR(?country);separator="|") AS ?countries)
  (GROUP_CONCAT(DISTINCT ?alt;separator="|") AS ?alts) WHERE {
  VALUES ?creator { wd:Q1 }
  OPTIONAL { ?creator rdfs:label ?label FILTER(LANG(?label) = "en") }
  OPTIONAL { ?creator wdt:P27 ?country }
  OPTIONAL { ?creator skos:altLabel ?alt FILTER(LANG(?alt) = "en") }
  OPTIONAL { ?creator wikibase:sitelinks ?sl }
  BIND(EXISTS { ?creator wdt:P31 wd:Q5 } AS ?human)
} GROUP BY ?creator ?label ?human ?sl

lookup_query_templates.country:
SELECT ?country ?label (GROUP_CONCAT(DISTINCT ?alt;separator="|") AS ?alts)
  (MIN(?end) AS ?dissolved) WHERE {
  VALUES ?country { wd:Q1 }
  OPTIONAL { ?country rdfs:label ?label FILTER(LANG(?label) = "en") }
  OPTIONAL { ?country skos:altLabel ?alt FILTER(LANG(?alt) = "en") }
  OPTIONAL { ?country wdt:P576 ?end }
} GROUP BY ?country ?label
